CREATE TABLE books (
  book_id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  shelf_code TEXT REFERENCES shelves(code),
  pages INTEGER CHECK (pages > 0)
);

SELECT book_id, title, pages
FROM books
ORDER BY pages DESC NULLS LAST, book_id;

function acceptDays(days) {
  return Number.isInteger(days) && days >= 1 && days <= 21;
}

function allowedDays(extended) {
  let days = 7; // S1
  if (extended) { // D1
    days = 21; // S2
  }
  return days; // S3
}

// 결함이 있던 조건
const before = days => Number.isInteger(days) && days >= 1 && days < 21;
// 수정한 조건: 합의한 상한을 포함한다
const after = days => Number.isInteger(days) && days >= 1 && days <= 21;
